QUESTION_KINDS = ["identity", "definition", "classification", "composition", "relationship", "state", "lifecycle", "temporal", "spatial", "provenance", "ownership", "authority", "requirement", "constraint", "process", "measurement", "evidence", "quality", "validation", "security", "privacy", "retention", "access", "exception", "interoperability", "decision"]


def structure():
    bundles = []
    n = 0
    for bid, bname, bdesc, rationale, brefs, layers in STRUCTURE:
        layer_rows = []
        for lid, lname, ldesc, lrefs, findings in layers:
            finding_rows = []
            for fid, fname, fdesc, primary_kind, frefs, value_kind, required, serial in findings:
                k2 = QUESTION_KINDS[(n + 7) % len(QUESTION_KINDS)]
                k3 = QUESTION_KINDS[(n + 16) % len(QUESTION_KINDS)]
                n += 1
                questions = [
                    {"id": f"{fid}-q01", "text": f"What governed budget assertion is recorded for {fname.lower()}, for which owner, scope, period, currency or unit, recognition basis and revision?", "kind": primary_kind, "answer_data": [fname, "owner, scope and period", "currency or unit, basis, status and revision"]},
                    {"id": f"{fid}-q02", "text": f"Which source, authority, method, assumptions and evidence establish {fname.lower()}, with what quality, uncertainty and limitations?", "kind": k2, "answer_data": ["source and authority", "method, assumptions and evidence", "quality, uncertainty and limitations"]},
                    {"id": f"{fid}-q03", "text": f"Which validation, access, approval or change rule governs {fname.lower()}, and how are affected predecessors, successors and external bindings preserved?", "kind": k3, "answer_data": ["validation, access and approval rule", "authorized action and effective time", "predecessor, successor and external reference"]},
                ]
                data_elements = [{"id": f"{fid}-data", "name": f"{fname} assertion", "description": f"Structured budget answer data for {fname.lower()}, including scope, period, basis, amount or reference, status and provenance.", "value_kind": value_kind, "cardinality": "1" if required else "0..n", "required": required, "source_refs": frefs}]
                artifacts = [{"id": f"{fid}-artifact", "name": f"{fname} record", "description": f"Versioned budget record supporting {fname.lower()} with authority, provenance, evidence and access marking.", "media_or_form": ["structured budget assertion", "decision or evidence statement", "resolvable execution or source index"], "serial": serial, "identity_strategy": "Authoritative budget master-system identifier first; otherwise a Dimension-governed UUID or ULID.", "source_refs": frefs}]
                finding_rows.append({"id": fid, "name": fname, "description": fdesc, "source_refs": frefs, "questions": questions, "data_elements": data_elements, "artifacts": artifacts, "inline_only_rationale": None})
            layer_rows.append({"id": lid, "name": lname, "description": ldesc, "source_refs": lrefs, "findings": finding_rows})
        bundles.append({"id": bid, "name": bname, "description": bdesc, "rationale": rationale, "source_refs": brefs, "layers": layer_rows})
    return {"bundles": bundles}


